303	    /** Sets the user's role on the sheet; refused unless it is clerk or steward. */
304	    @Transactional
305	    public SheetRole setRole(String by, String sheetId, String user, String role) {
306	        if (!SheetRole.CLERK.equals(role) && !SheetRole.STEWARD.equals(role)) {
307	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A role is clerk or steward.");
308	        }
309	        sheets.lock(sheetId);
310	        SheetRole r = roles.findBySheetIdAndUser(sheetId, user).orElseGet(() -> new SheetRole(sheetId, user, role));
311	        r.setRole(role);
312	        SheetRole saved;
313	        try {
314	            saved = roles.saveAndFlush(r);
315	        } catch (DataIntegrityViolationException e) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That role was just set by someone else.");
317	        }
318	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role);
319	        return saved;
320	    }
