427	        Sheet sheet = sheets.lock(sheetId);
428	        RollupService.Snapshot before = rollup.snapshot(sheetId);
429	        BigDecimal scaled = floor.setScale(2, RoundingMode.UNNECESSARY);
430	        sheet.setFloor(scaled);
431	        Sheet saved = sheetRepository.saveAndFlush(sheet);
432	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=floor value="
433	                + scaled.toPlainString());
434	        rollup.recordChanges(by, sheetId, before);
435	        return saved;
436	    }
