438	    /**
439	     * Sets the sheet's cap (null for none): the most a person's due-total can be. The due-totals it moves are rolled
440	     * up.
441	     */
442	    @Transactional
443	    public Sheet setCap(String by, String sheetId, BigDecimal cap) {
444	        Sheet sheet = sheets.lock(sheetId);
445	        RollupService.Snapshot before = rollup.snapshot(sheetId);
446	        BigDecimal scaled = cap == null ? null : cap.setScale(2, RoundingMode.UNNECESSARY);
447	        sheet.setCap(scaled);
448	        Sheet saved = sheetRepository.saveAndFlush(sheet);
449	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=cap value="
450	                + (scaled == null ? "" : scaled.toPlainString()));
451	        rollup.recordChanges(by, sheetId, before);
452	        return saved;
453	    }
454	
455	    /**
456	     * Whether the user settling a claim with the due (null for n/a) needs a steward's approval: they are a clerk and
457	     * the due is above the sheet's clerk limit. A steward settles anything, and an n/a due is within any limit.
458	     */
459	    @Transactional(readOnly = true)
460	    public boolean aboveClerkLimit(String sheetId, String user, BigDecimal due) {
461	        BigDecimal limit = sheets.load(sheetId).getClerkLimit();
462	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
463	            return false;
464	        }
465	        return !isSteward(sheetId, user);
466	    }
