579	export const ROLES = ['clerk', 'steward'];
580	
581	const LIMIT = /^\d{1,12}(\.\d{1,2})?$/;
582	
583	/** The floor a sheet starts with. */
584	export const DEFAULT_FLOOR = '1.00';
585	
586	/** The terms a sheet starts with, in days. */
587	export const DEFAULT_TERMS = 14;
588	
589	const DAYS = /^\d{1,5}$/;
590	
591	/** The late percent a sheet starts with. */
592	export const DEFAULT_LATE_PCT = '0.00';
593	
594	const PCT = /^\d{1,5}(\.\d{1,2})?$/;
595	
596	const DATE = /^\d{4}-\d{2}-\d{2}$/;
597	
598	// The active sheet's settings: the role set for each user name (any other name is a clerk), the clerk limit and
599	// the floor, the terms, the late percent, the policy date and the period numbering from.
600	@Injectable({ providedIn: 'root' })
601	export class SettingsStore {
602	  private readonly http = inject(HttpClient);
603	  private readonly session = inject(Session);
604	
605	  readonly roles = signal<readonly RoleView[]>([]);
606	  readonly clerkLimit = signal<string | null>(null);
607	  readonly floor = signal<string>(DEFAULT_FLOOR);
608	  readonly terms = signal<number>(DEFAULT_TERMS);
609	  /** The terms set per grade, by grade; a grade not in it uses the sheet's terms. */
610	  readonly gradeTerms = signal<ReadonlyMap<string, number>>(new Map());
611	  readonly latePct = signal<string>(DEFAULT_LATE_PCT);
612	  /** The policy date as set; null when blank. */
613	  readonly policyDate = signal<string | null>(null);
614	  /** The period numbering from as set; null when blank (off). */
615	  readonly periodNumberingFrom = signal<string | null>(null);
616	  /** The cap as set; null when blank (none). */
617	  readonly cap = signal<string | null>(null);
618	  /**
619	   * What an overdue claim's late charge follows: the sheet's today and the late percent; and the policy
620	   * date in force (the sheet's today when blank), which decides how live figures round.
621	   */
622	  readonly lateness = computed(() => ({
623	    today: this.session.sheetToday(),
624	    latePct: this.latePct(),
625	    policyDate: this.policyDate() ?? this.session.sheetToday(),
626	  }));
627	
628	  /** Re-read the sheet's settings from the store. */
629	  async load(sheet: string): Promise<void> {
630	    this.roles.set([]);
631	    this.clerkLimit.set(null);
632	    this.floor.set(DEFAULT_FLOOR);
633	    this.terms.set(DEFAULT_TERMS);
634	    this.gradeTerms.set(new Map());
635	    this.latePct.set(DEFAULT_LATE_PCT);
636	    this.policyDate.set(null);
637	    this.periodNumberingFrom.set(null);
638	    this.cap.set(null);
639	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
640	    const [roles, settings, gradeTerms] = await Promise.all([
641	      firstValueFrom(this.http.get<RoleView[]>(`${base}/roles`)),
642	      firstValueFrom(this.http.get<SettingsView>(`${base}/settings`)),
643	      firstValueFrom(this.http.get<GradeTermsView[]>(`${base}/settings/grade-terms`)),
