896	  protected readonly floor = signal('');
897	  protected readonly terms = signal('');
898	  protected readonly gradeTerms = signal<Readonly<Record<string, string>>>({});
899	  protected readonly latePct = signal('');
900	  protected readonly policyDate = signal('');
901	  protected readonly periodNumberingFrom = signal('');
902	  protected readonly cap = signal('');
903	  // Which settings were typed into since the last save; a save stores only those. Erasing in a field counts, so
904	  // clearing one that already shows blank (as the clerk limit, for none) still saves it.
905	  protected limitChanged = false;
906	  protected floorChanged = false;
907	  protected termsChanged = false;
908	  protected readonly gradeTermsChanged = new Set<string>();
909	  protected latePctChanged = false;
910	  protected policyDateChanged = false;
911	  protected periodNumberingFromChanged = false;
912	  protected capChanged = false;
913	  protected readonly user = signal('');
914	  protected readonly role = signal('');
915	  protected readonly settingsError = signal<string | null>(null);
916	  protected readonly roleError = signal<string | null>(null);
917	  // A settings submit in flight, and whether another came before it answered: that one runs once it has.
918	  private savingSettings = false;
919	  private resubmit = false;
920	  // A role submit in flight: a second one before it answers is ignored.
921	  private submitting = false;
922	
923	  constructor() {
924	    // Re-read the settings from the store each time a sheet is loaded.
925	    effect(() => {
926	      const id = this.session.sheetId();
927	      this.session.loads();
928	      untracked(() => {
929	        this.settingsError.set(null);
930	        this.roleError.set(null);
931	        if (id) this.store.load(id).catch(() => this.settingsError.set('Could not load the settings.'));
932	      });
933	    });
934	  }
935	
936	  protected value(e: Event): string {
937	    return (e.target as HTMLInputElement).value;
938	  }
939	
940	  protected setGradeTermsField(grade: string, v: string): void {
941	    this.gradeTerms.update((t) => ({ ...t, [grade]: v }));
942	    this.gradeTermsChanged.add(grade);
943	    this.settingsError.set(null);
944	  }
945	
946	  protected async saveSettings(e: Event): Promise<void> {
947	    e.preventDefault();
948	    if (this.savingSettings) {
949	      // saved once the one in flight answers, so a value typed meanwhile is not lost
950	      this.resubmit = true;
951	      return;
952	    }
953	    this.settingsError.set(null);
954	    const sheet = this.session.sheetId();
955	    if (!sheet) return;
956	    const limit = this.limit().trim();
957	    if (this.limitChanged && limit && !LIMIT.test(limit)) {
958	      this.settingsError.set('Enter a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
959	      return;
960	    }
961	    const floor = this.floor().trim();
962	    if (this.floorChanged && !LIMIT.test(floor)) {
963	      this.settingsError.set('Enter a floor of 0.00 or more, with up to two decimals.');
964	      return;
965	    }
966	    const terms = this.terms().trim();
967	    if (this.termsChanged && !DAYS.test(terms)) {
968	      this.settingsError.set('Enter terms as a whole number of days, 0 or more.');
969	      return;
970	    }
971	    const gradeTerms = new Map<string, string>();
972	    for (const g of this.gradeTermsChanged) gradeTerms.set(g, (this.gradeTerms()[g] ?? '').trim());
973	    for (const [g, t] of gradeTerms) {
974	      if (!DAYS.test(t)) {
975	        this.settingsError.set(`Enter terms for grade ${g} as a whole number of days, 0 or more.`);
976	        return;
977	      }
978	    }
979	    const latePct = this.latePct().trim();
980	    if (this.latePctChanged && !PCT.test(latePct)) {
981	      this.settingsError.set('Enter a late percent of 0.00 or more, with up to two decimals.');
982	      return;
983	    }
984	    const policyDate = this.policyDate().trim();
985	    if (this.policyDateChanged && policyDate && !DATE.test(policyDate)) {
986	      this.settingsError.set('Enter a policy date, or leave it blank for the sheet\'s today.');
987	      return;
988	    }
989	    const periodNumberingFrom = this.periodNumberingFrom().trim();
990	    if (this.periodNumberingFromChanged && periodNumberingFrom && !DATE.test(periodNumberingFrom)) {
991	      this.settingsError.set('Enter a period numbering from date, or leave it blank for off.');
992	      return;
993	    }
994	    const cap = this.cap().trim();
995	    if (this.capChanged && cap && !LIMIT.test(cap)) {
996	      this.settingsError.set('Enter a cap of 0.00 or more, with up to two decimals, or leave it blank.');
997	      return;
998	    }
999	    this.savingSettings = true;
1000	    try {
1001	      if (this.limitChanged) {
1002	        await this.store.setClerkLimit(sheet, limit || null);
1003	        // a value typed while it was saving stays to be saved
1004	        this.limitChanged = this.limit().trim() !== limit;
1005	      }
1006	      if (this.floorChanged) {
1007	        await this.store.setFloor(sheet, floor);
1008	        this.floorChanged = this.floor().trim() !== floor;
1009	      }
1010	      if (this.termsChanged) {
1011	        await this.store.setTerms(sheet, Number(terms));
1012	        this.termsChanged = this.terms().trim() !== terms;
1013	      }
1014	      for (const [g, t] of gradeTerms) {
1015	        await this.store.setGradeTerms(sheet, g, Number(t));
1016	        if ((this.gradeTerms()[g] ?? '').trim() === t) this.gradeTermsChanged.delete(g);
1017	      }
1018	      if (this.latePctChanged) {
1019	        await this.store.setLatePct(sheet, latePct);
1020	        this.latePctChanged = this.latePct().trim() !== latePct;
1021	      }
1022	      if (this.policyDateChanged) {
1023	        await this.store.setPolicyDate(sheet, policyDate || null);
1024	        this.policyDateChanged = this.policyDate().trim() !== policyDate;
1025	      }
1026	      if (this.periodNumberingFromChanged) {
1027	        await this.store.setPeriodNumberingFrom(sheet, periodNumberingFrom || null);
1028	        this.periodNumberingFromChanged = this.periodNumberingFrom().trim() !== periodNumberingFrom;
1029	      }
1030	      if (this.capChanged) {
1031	        await this.store.setCap(sheet, cap || null);
1032	        this.capChanged = this.cap().trim() !== cap;
1033	      }
1034	    } catch {
1035	      this.resubmit = false;
1036	      this.settingsError.set('Could not save the settings.');
1037	    } finally {
1038	      this.savingSettings = false;
1039	    }
1040	    if (this.resubmit) {
1041	      this.resubmit = false;
1042	      await this.saveSettings(e);
1043	    }
1044	  }
1045	
1046	  protected async saveRole(e: Event): Promise<void> {
1047	    e.preventDefault();
1048	    if (this.submitting) return;
1049	    this.roleError.set(null);
1050	    const sheet = this.session.sheetId();
1051	    if (!sheet) return;
1052	    const user = this.user().trim();
1053	    const role = this.role().trim();
1054	    if (!user) {
1055	      this.roleError.set('Enter a user name.');
1056	      return;
1057	    }
1058	    if (!ROLES.includes(role)) {
1059	      this.roleError.set('Choose a role of clerk or steward.');
1060	      return;
1061	    }
1062	    this.submitting = true;
1063	    try {
1064	      await this.store.setRole(sheet, user, role);
1065	    } catch {
1066	      this.roleError.set('Could not set that role.');
1067	    } finally {
