import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { PeriodStore, inClosedPeriod, periodOn } from '../periods/periods';
import { DatedGrade, RateStore, RateView, atLeast, dueOn, gradeOn, rateOn, withPctPer } from '../rates/rates';
import { SettingsStore } from '../settings/settings';

export interface Claim {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  // Given when the claim is opened: the sheet's next (1, 2, ...) or, while the sheet numbers by period, its
  // period's next (P1-1; X-1 for no period); null for a claim never opened.
  number: string | null;
  // The due fixed when the claim was settled; null while its due is live.
  settledDue: string | null;

/**
 * Whether the claim's live figures round half up: when the date its rounding follows is before the policy date
 * (the sheet's today when the setting is blank); else they round half to even.
 */
export function roundsHalfUp(c: Claim, policyDate: string | null): boolean {
  return policyDate !== null && c.roundsOn < policyDate;
}

/**
 * The figure a claim shows and totals: its settled due, else the one a statement bound it to (not while it is
 * pending), else its live due
 * at the rate in force on its date and at least the floor (a correction has none), rounded as the policy date
 * decides for it; null (n/a) with none.
 */
export function figureOf(c: Claim, rates: readonly RateView[], floor: string, policyDate: string | null): string | null {
  if (c.settledDue !== null) return c.settledDue;
  if (isBound(c)) return c.statedDue;
  const due = dueOn(c.amount, rateOn(rates, c.date), roundsHalfUp(c, policyDate));
  return due === null || isCorrection(c) ? due : atLeast(due, floor);
}

/** Whether the claim keeps a figure whatever the rates: a settled or bound one with a figure. */
export function keepsFigure(c: Claim): boolean {
  return c.settledDue !== null || (isBound(c) && c.statedDue !== null);
}

/** Whether a claim is overdue: open (or pending), and due by a date before the sheet's today. */
export function overdue(c: Claim, today: string | null): boolean {
  return isOpen(c) && today !== null && c.dueBy < today;
}

/**
 * What the late charge follows: the sheet's today and its late percent; and the policy date in force
 * (the sheet's today when the setting is blank), which decides how a claim's live figures round.
 */
export interface Lateness {
  today: string | null;
  latePct: string;
  policyDate: string | null;
}

/** The whole days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  const utc = (d: string) => {
    const [y, m, day] = d.split('-').map(Number);
    return Date.UTC(y, m - 1, day);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/**
 * The due a claim shows and totals: its figure, and for an overdue claim the late percent of that figure for
 * every full 30 days it is overdue, added on top. The charge is never bound by a statement; a settled claim's
 * due already holds it. A correction gains no late charge.
 */
export function dueOf(c: Claim, rates: readonly RateView[], floor: string, late: Lateness): string | null {
  const figure = figureOf(c, rates, floor, late.policyDate);
  if (figure === null || isCorrection(c) || !overdue(c, late.today)) return figure;
  const periods = Math.floor(daysBetween(c.dueBy, late.today!) / 30);
  return withPctPer(figure, late.latePct, periods, roundsHalfUp(c, late.policyDate));
}

const CLOSED = 'That claim is dated in a closed period, so it cannot change.';

export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** A claim form's amount: a negative one is a correction. */
const SIGNED_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/** The sum of the counted claims' amounts, with two decimals; added in whole cents so nothing drifts. */
  // Each person's due-total: the sum of their counted claims' figures, each settled one's frozen figure or
  // the one a statement bound it to, or its live due, skipping n/a. With no rate in force today for their grade
  // today nor for the grade of any counted claim's date it is null (n/a), unless a counted claim has a figure (a
  // settled or stated one, or one dated within a rate that has since ended). This is before the sheet's cap.
  private readonly uncappedDueBy = computed(() => {
    const by = new Map<number, string | null>();
    const current = this.rates.current();
    const rates = this.rates.rates();
    const floor = this.settings.floor();
    const late = this.settings.lateness();
    for (const p of this.people()) {
      const counted = this.liveBy().get(p.id) ?? [];
      // the grades whose rate today decides n/a: the one in force today and each counted claim's
      const grades = [this.gradeToday(p), ...counted.map((c) => gradeOn(p.grades, c.date))];
      const dues = counted.map((c) => dueOf(c, rates.get(gradeOn(p.grades, c.date)) ?? [], floor, late));
      if (!grades.some((g) => current.has(g)) && dues.every((d) => d === null)) {
        by.set(p.id, null);
        continue;
      }
      by.set(p.id, sumSkippingNa(dues));
    }
    return by;
  });
  // Each person's due-total held to the sheet's cap; everything that adds up due-totals uses it. n/a is not capped.
  protected readonly dueBy = computed(() => {
    const cap = this.settings.cap();
    const by = new Map<number, string | null>();
    for (const [id, due] of this.uncappedDueBy()) by.set(id, atMost(due, cap));
    return by;
  });
  // Each person's excess: what their due-total is above the sheet's cap, else 0.00.
  protected readonly excessBy = computed(() => {
    const cap = this.settings.cap();
    const by = new Map<number, string>();
    for (const [id, due] of this.uncappedDueBy()) by.set(id, excessOver(due, cap));
    return by;
  });
  // Every claim counted live: its person, its date and the figure it totals, for the periods' due-totals.
  protected readonly countedFigures = computed<DatedFigure[]>(() => {
    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
    const rates = this.rates.rates();
    const floor = this.settings.floor();
    const late = this.settings.lateness();
    return this.liveClaims().map((c) => {
      const grade = gradeOn(grades.get(c.personId) ?? [], c.date);
      return { personId: c.personId, date: c.date, figure: dueOf(c, rates.get(grade) ?? [], floor, late) };
    });
  });
  // Each person's due-total for each period, by person id then period id: a closed period's figure fixed for them
  // when it closed, else their counted claims' figures dated in it, skipping n/a.
  protected readonly periodDueBy = computed(() => {
    const by = new Map<number, Claim[]>();
    for (const c of this.overdueClaims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
    return by;
  });
  // Each person's overdue-total: the sum of their overdue claims' figures, skipping n/a.
  protected readonly overdueTotalBy = computed(() => {
    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
    const rates = this.rates.rates();
    const floor = this.settings.floor();
    const late = this.settings.lateness();
    const by = new Map<number, string>();
    for (const [id, list] of this.overdueBy()) {
      const own = grades.get(id) ?? [];
      by.set(id, sumSkippingNa(list.map((c) => dueOf(c, rates.get(gradeOn(own, c.date)) ?? [], floor, late))));
    }
    return by;
  });
  protected readonly overdueTotal = computed(() => sumSkippingNa([...this.overdueTotalBy().values()]));
  return formatCents(values.reduce((sum, v) => (v === null ? sum : sum + cents(v)), 0n));
}

/**
 * The percent of the rate in force on the date among one grade's rates: the one with the latest
 * from-date on or before it, a rate with no from-date applying from the beginning of time;
 * undefined (n/a) when none applies yet, or when the date is past that one's to-date.
 */
export function rateOn(rates: readonly RateView[], date: string | null): string | undefined {
  let best: RateView | undefined;
  for (const r of rates) {
    if (r.from !== null && (date === null || r.from > date)) continue;
    if (!best || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
  }
  if (best?.to && date !== null && date > best.to) return undefined;
  return best?.pct;

